import random


MAX_SAMPLE_COUNT = 2


class ReplayBuffer:
    def __init__(self, buffer_size):
        self.buffer = []
        self.buffer_size = buffer_size

    def add(self, state, action, reward, next_state, done):
        self.last_state = state
        experience = {
            "state": state,
            "action": action,
            "reward": reward,
            "next_state": next_state,
            "done": done,
            "sample_count": 0,
        }
        if len(self.buffer) > self.buffer_size:
            self.buffer[random.randint(0, self.buffer_size)] = experience
        else:
            self.buffer.append(experience)

    def add_batch(self, states, actions, rewards, next_states, dones):
        batch = [
            {
                "state": state,
                "action": action,
                "reward": reward,
                "next_state": next_state,
                "done": done,
                "sample_count": 0,
            }
            for state, action, next_state, reward, done in zip(
                states, actions, rewards, next_states, dones
            )
        ]
        for item in batch:
            self.add(*item.values()[:-1])

    def sample(self):
        index = random.sample(range(len(self.buffer)), 1)[0]
        state, action, reward, next_state, done, sample_count = self.buffer[index].values()
        sample_count += 1
        if sample_count > MAX_SAMPLE_COUNT:
            self.buffer.pop(index)
        return state, action, reward, next_state, done

    def get_last_state(self):
        return self.last_state
